// Generate 40 historical records
export const MOCK_HISTORY_RECORDS: HistoryRecord[] = Array.from({ length: 40 }).map((_, idx) => {
  const hoursAgo = Math.floor(idx / 3) + 1;
  const minutesAgo = (idx * 17) % 60;
  const timestamp = new Date(DEMO_TIME - (hoursAgo * 3600 + minutesAgo * 60) * 1000);
  const route = ['64', '40', '8', 'H', '70', '492', '170', '3', '51', '916'][idx % 10];
  const delaySec = Math.floor(Math.sin(idx * 1.3) * 320 + 240);
  const prob = Math.min(0.96, Math.max(0.04, delaySec / 600 + (idx % 4 === 0 ? 0.25 : -0.1)));
  const isMajor = prob >= 0.35;
  const stopKeys = Object.keys(DEMO_STOPS);
  const stopId = stopKeys[idx % stopKeys.length];

  return {
    id: 1000 + idx,
    created_at: timestamp.toISOString(),
    prediction_generated_at: timestamp.toISOString(),
    source_feed_timestamp: Math.floor(timestamp.getTime() / 1000) - 120,
    entity_id: `entity_rome_${idx + 101}`,
    route_id: route,
    trip_id: `trip_${route}_${10000 + idx}`,
    vehicle_id: `ATAC_${2000 + (idx * 23) % 900}`,
    stop_id: stopId,
    stop_name: DEMO_STOPS[stopId],
    stop_sequence: (idx % 25) + 1,
    target_next_stop_id: stopKeys[(idx + 1) % stopKeys.length],
    current_arrival_delay_seconds: Math.max(-60, delaySec),
    major_delay_probability: Number(prob.toFixed(3)),
    predicted_major_delay: isMajor,
    model_version: 'demo-model-not-loaded',
    feature_contract_hash: 'demo-no-feature-hash',
    threshold: 0.35,
    source_silver_version: 5,
    feature_preparation_batch_id: `batch_20261028_${10 + (idx % 8)}`,
  };
});

export const MOCK_HISTORY_RESPONSE: HistoryResponse = {
  rows: MOCK_HISTORY_RECORDS.length,
  query_generated_at: NOW_ISO,
  predictions: MOCK_HISTORY_RECORDS,
};

